'use strict';
const fs = require('fs');

(function main() {
  const data = fs.readFileSync(0);
  const len = data.length;
  let ptr = 0;

  function readInt() {
    while (ptr < len) {
      const c = data[ptr];
      if ((c >= 48 && c <= 57) || c === 45) break;
      ptr++;
    }
    let neg = false;
    if (ptr < len && data[ptr] === 45) { neg = true; ptr++; }
    let x = 0;
    while (ptr < len) {
      const c = data[ptr];
      if (c < 48 || c > 57) break;
      x = x * 10 + (c - 48);
      ptr++;
    }
    return neg ? -x : x;
  }

  const L = readInt();
  const C = readInt();
  const N = L * C;
  const A = new Int32Array(N);
  for (let i = 0; i < N; i++) A[i] = readInt();

  // Super-legal <=> every 2x2 is Monge:
  // bad cell in delta grid: D[p][q] = A[p][q]+A[p+1][q+1]-A[p][q+1]-A[p+1][q] > 0
  // Rect [r1..r2]x[c1..c2] valid iff no bad delta cell in [r1..r2-1]x[c1..c2-1].
  // Answer: max (r2-r1+1)*(c2-c1+1), needs h>=2,w>=2 (else "no super-legal submatrix" -> 0).
  const cl = C - 1;
  const INF = 0x7fffffff;

  const firstBad = new Int32Array(cl).fill(INF);

  const parent = new Int32Array(cl);
  const size = new Int32Array(cl);
  const added = new Uint8Array(cl);
  const head = new Int32Array(L + 1); // index L = bucket for firstBad == INF (never bad below current r1)
  const nxt = new Int32Array(cl);

  let ans = 0;
  let maxRun = 0;

  function find(x) {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }

  function addCol(q) {
    added[q] = 1;
    parent[q] = q;
    size[q] = 1;
    if (maxRun < 1) maxRun = 1;
    if (q > 0 && added[q - 1]) {
      const ra = find(q), rb = find(q - 1);
      if (ra !== rb) {
        if (size[ra] < size[rb]) { parent[ra] = rb; size[rb] += size[ra]; if (size[rb] > maxRun) maxRun = size[rb]; }
        else { parent[rb] = ra; size[ra] += size[rb]; if (size[ra] > maxRun) maxRun = size[ra]; }
      }
    }
    if (q + 1 < cl && added[q + 1]) {
      const ra = find(q), rb = find(q + 1);
      if (ra !== rb) {
        if (size[ra] < size[rb]) { parent[ra] = rb; size[rb] += size[ra]; if (size[rb] > maxRun) maxRun = size[rb]; }
        else { parent[rb] = ra; size[ra] += size[rb]; if (size[ra] > maxRun) maxRun = size[ra]; }
      }
    }
  }

  for (let r1 = L - 2; r1 >= 0; r1--) {
    const a1 = r1 * C;
    const a2 = a1 + C;

    // incorporate delta row r1 into firstBad (min bad delta-row >= r1 per column)
    for (let q = 0; q < cl; q++) {
      if (A[a1 + q] + A[a2 + q + 1] > A[a1 + q + 1] + A[a2 + q]) firstBad[q] = r1;
    }

    // bucket columns by first bad row
    for (let k = 0; k <= L; k++) head[k] = -1;
    for (let q = 0; q < cl; q++) {
      const v = firstBad[q];
      const idx = (v === INF) ? L : v;
      nxt[q] = head[idx];
      head[idx] = q;
    }

    // reset per-r1 state
    for (let q = 0; q < cl; q++) added[q] = 0;
    maxRun = 0;

    // columns never bad below r1 are good for every r2
    for (let q = head[L]; q !== -1; q = nxt[q]) addCol(q);

    // sweep r2 from bottom to r1+1 (threshold: good cols have firstBad >= r2), only additions -> DSU merges
    for (let r2 = L - 1; r2 > r1; r2--) {
      for (let q = head[r2]; q !== -1; q = nxt[q]) addCol(q);
      if (maxRun > 0) {
        const area = (r2 - r1 + 1) * (maxRun + 1);
        if (area > ans) ans = area;
      }
    }
  }

  process.stdout.write(ans + '\n');
})();
